 if(![1,3].includes(codec)||![1,2].includes(channels)||sampleRate<8000||sampleRate>96000||![16,32].includes(bits)||codec===3&&bits!==32||block!==channels*bits/8||data.length%block)throw failure('仅支持有效的 PCM/浮点 WAV 音频');
